
/* ===== 이순신 연대기 전용 인물 그림 =====
   '이순신_연대기_캐릭터.png'에서 오려 낸 도트 그림이에요. 이순신 연대기(제1~7화)에서만 쓰고,
   다른 이야기(다윗 외전·본편)의 그림은 그대로 둬요. 포켓몬 대사는 원래대로 포켓몬 그림이 나와요. */
(function(){
 const ART={"kid": "data:image/webp;base64,", "teen": "data:image/webp;base64,", "white": "data:image/webp;base64,", "officer": "data:image/webp;base64,", "helm1": "data:image/webp;base64,", "helm2": "data:image/webp;base64,", "helm3": "data:image/webp;base64,", "scarf": "data:image/webp;base64,", "admiral": "data:image/webp;base64,", "ryu_young": "data:image/webp;base64,", "ryu": "data:image/webp;base64,", "examiner": "data:image/webp;base64,", "shin1": "data:image/webp;base64,", "shin2": "data:image/webp;base64,", "shin3": "data:image/webp;base64,", "gwanri": "data:image/webp;base64,", "jeongtak": "data:image/webp;base64,", "sold_a": "data:image/webp;base64,", "sold_b": "data:image/webp;base64,", "sold_c": "data:image/webp;base64,", "sold_helm": "data:image/webp;base64,", "il": "data:image/webp;base64,", "seongbak": "data:image/webp;base64,", "sanggwan": "data:image/webp;base64,", "messenger": "data:image/webp;base64,", "ch1": "data:image/webp;base64,", "ch2": "data:image/webp;base64,", "ch3": "data:image/webp;base64,", "ch4": "data:image/webp;base64,", "friend1": "data:image/webp;base64,", "friend2": "data:image/webp;base64,", "child": "data:image/webp;base64,", "shipwright": "data:image/webp;base64,", "jeongun": "data:image/webp;base64,", "wongyun": "data:image/webp;base64,", "yieokgi": "data:image/webp;base64,", "wakizaka": "data:image/webp;base64,", "jp_soldier": "data:image/webp;base64,", "yoshira": "data:image/webp;base64,", "anwi": "data:image/webp;base64,", "jinrin": "data:image/webp;base64,", "gwonyul": "data:image/webp;base64,", "general": "data:image/webp;base64,", "ihoe": "data:image/webp;base64,", "iwan": "data:image/webp;base64,", "vil_old": "data:image/webp;base64,", "vil_granny": "data:image/webp;base64,", "vil_man": "data:image/webp;base64,", "vil_woman": "data:image/webp;base64,"};
 const prev=window.scSpeakerArt;if(typeof prev!=='function')return;
 const img=k=>`<div class="sc-portrait sc-pixelportrait sc-art-portrait"><img src="${ART[k]}" alt=""></div>`;
 const hs=s=>{let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return h;};
 const pick=(a,w)=>a[hs(w)%a.length];
 /* 순신: 나이와 장면에 맞춰 모습이 바뀌어요 (n = 몇 화, pos = 장면 번호) */
 const heroKey=(n,pos)=>{
  if(n===1)return pos<43?'kid':pos<78?'teen':'officer';          // 골목대장 → 시험 준비 → 합격
  if(n===2)return (pos>=95&&pos<134)?'white':'officer';          // 제8~9장: 백의종군(하얀 옷)
  if(n===3)return pos<13?'officer':'helm1';                      // 전라좌수사가 되면서 투구
  if(n===4)return 'helm2';                                       // 옥포·사천·한산도
  if(n===5)return pos<22?'admiral':pos<44?'officer':pos<71?'white':'admiral'; // 감옥 → 두 번째 백의종군 → 통제사 복귀
  if(n===6)return 'admiral';                                     // 명량
  return pos<47?'admiral':'helm3';                               // 노량
 };
 const NAMED={'시험관':'examiner','구경꾼 1':'vil_man','구경꾼 2':'vil_woman','도전자 1':'ch1','도전자 2':'ch2','도전자 3':'ch3','도전자 4':'ch4','도전자들':'ch2',
  '친구 1':'friend1','친구 2':'friend2','막내':'child','아이':'child','병사':'sold_a','병사 1':'sold_b','병사 2':'sold_c','병사들':'sold_helm','동료 병사':'sold_a',
  '일본군 병사':'jp_soldier','장수':'general','성박':'seongbak','상관':'sanggwan','이일':'il','전령':'messenger','신하 1':'shin1','신하 2':'shin2','조정 신하':'shin3',
  '관리':'gwanri','정탁':'jeongtak','정운':'jeongun','나대용':'shipwright','원균':'wongyun','이억기':'yieokgi','요시라':'yoshira','와키자카':'wakizaka','진린':'jinrin',
  '권율':'gwonyul','안위':'anwi','이회':'ihoe','이완':'iwan','백성':'vil_man','백성 1':'vil_old','백성 2':'vil_granny'};
 function yiKey(w,n,pos){
  if(w==='순신')return heroKey(n,pos);
  if(w==='류성룡')return n===1?'ryu_young':'ryu';                // 어릴 땐 책 읽는 형, 이후엔 관복 차림
  if(NAMED[w])return NAMED[w];
  let m=0;try{m=scMonId(w);}catch(e){}
  if(m)return null;                                              // 포켓몬은 원래 그림 그대로
  if(/도전자/.test(w))return pick(['ch1','ch2','ch3','ch4'],w);
  if(/일본군|왜군|왜장|적장/.test(w))return 'jp_soldier';
  if(/병사|군사|수군/.test(w))return pick(['sold_a','sold_b','sold_c'],w);
  if(/백성|주민/.test(w))return pick(['vil_man','vil_woman','vil_old','vil_granny'],w);
  if(/구경꾼/.test(w))return pick(['vil_man','vil_woman','vil_old'],w);
  if(/신하|관리|대감/.test(w))return pick(['shin1','shin2','shin3','gwanri'],w);
  if(/장수|장군|대장/.test(w))return 'general';
  if(/아이|어린이/.test(w))return 'child';
  return null;
 }
 window.scSpeakerArt=function(who,u,pos){
  try{
   const w=String(who||'').trim();
   const uu=(typeof u==='number')?u:(typeof SC!=='undefined'?SC.unit:-1);
   const pp=(typeof pos==='number')?pos:(typeof SC!=='undefined'&&SC.pos!=null?SC.pos:0);
   if(typeof scIsYi==='function'&&scIsYi(uu)){
    const k=yiKey(w,uu-SC_YI_START+1,pp);
    if(k&&ART[k])return img(k);
   }
  }catch(e){}
  return prev.apply(this,arguments);
 };
 window.scYiHeroArt=(u,pos)=>{try{const k=heroKey(u-SC_YI_START+1,typeof pos==='number'?pos:0);return ART[k]||null;}catch(e){return null;}};
 /* 목록 카드·표지에 쓰는 대표 그림 (화별 순신) */
 const FACE={1:'kid',2:'officer',3:'helm1',4:'scarf',5:'white',6:'admiral',7:'helm3'};
 const faceKey=n=>typeof n==='number'?FACE[n]:n;
 window.scYiFace=n=>{const k=faceKey(n);return ART[k]?`<img class="scv-yi-face" src="${ART[k]}" alt="">`:'';};
 window.scYiCover=u=>{const k=FACE[u-SC_YI_START+1];return ART[k]?`<img class="scv-yi-cover" src="${ART[k]}" alt="">`:'';};
})();
